goto_if_eq VAR_RESULT CONTEST_CATEGORY_BEAUTY LilycoveCity_PokemonCenter_1F_EventScript_Skitty
goto_if_eq VAR_RESULT CONTEST_CATEGORY_CUTE LilycoveCity_PokemonCenter_1F_EventScript_Poochyena
